'use client'

import './console.css'
import { Fragment, useEffect, useState } from 'react'
import { Check, ChevronDown, Clipboard, Download, ExternalLink, Eye, LoaderCircle, Play, Plus, Search, TriangleAlert } from 'lucide-react'
import { MOCK, askScout, discoverMcpTools, getDecisions, getJournal, mockResumeResponse, mockStartResponse, recruitOutreach, resumeRun, saveDecision, startRun, getWatchlist, setWatch, refreshWatch, type Journal, type JournalEntry, type MomTest, type ProposedFeature, type Question, type WatchEntry, type Alert, type Decision, type Evidence, type FinalResponse, type Pain, type Signal, type StartResponse, type Step4 } from '@/lib/scout-api'
import { scoreQuestion } from '@/lib/momtest'
import { track } from '@/lib/track'

type Phase = 'idle' | 'running' | 'paused' | 'done'
type NavState = 'locked' | 'ready' | 'attention'
type Run = { threadId: string; resumeToken: string; step4: Step4; final: FinalResponse | null }
const navItems = ['Radar', 'Competition', 'Interviews', 'Roadmap']
const STORE = 'scout-console-run'
// Live API sends `closes` as a single id string and `who` as an array; mock predates that.
const asList = (v: unknown): string[] => Array.isArray(v) ? v.filter(Boolean).map(String) : (typeof v === 'string' && v ? [v] : [])
const asText = (v: unknown): string => Array.isArray(v) ? v.join(', ') : (v == null ? '' : String(v))
const ago = (iso: string | null): string => { if (!iso) return 'never listened'; const h = (Date.now() - new Date(iso).getTime()) / 36e5; if (h < 1.5) return 'just now'; if (h < 36) return `${Math.round(h)}h ago`; return `${Math.round(h / 24)}d ago` }
const errText = (e: unknown, fallback: string): string => { const d = (e as { detail?: unknown })?.detail; if (typeof d === 'string') return d; if (Array.isArray(d)) return d.map((x) => (x as {msg?:string})?.msg ?? JSON.stringify(x)).join(' · '); return fallback }

export default function Page() {
  const [brief, setBrief] = useState('')
  const [mode, setMode] = useState<'product' | 'industry'>('product')
  const [loops, setLoops] = useState('2')
  const [phase, setPhase] = useState<Phase>('idle')
  const [run, setRun] = useState<Run | null>(null)
  const [error, setError] = useState('')
  const [elapsed, setElapsed] = useState(0)
  const [selectedNav, setSelectedNav] = useState(0)
  const [watchlist, setWatchlist] = useState<WatchEntry[]>([])
  const [refreshing, setRefreshing] = useState<Record<string, boolean>>({})

  const loadWatchlist = async (): Promise<WatchEntry[]> => {
    if (MOCK) return []
    try { const w = await getWatchlist(); setWatchlist(w.watched ?? []); return w.watched ?? [] } catch { return [] }
  }

  // Mechanism A — stale-while-revalidate on visit: any watched subject whose
  // last listening pass is older than a week gets one kicked off in the
  // background the moment someone opens the console.
  useEffect(() => {
    if (MOCK) return
    ;(async () => {
      const watched = await loadWatchlist()
      watched.filter(w => w.stale && !w.refreshing).forEach(w => {
        setRefreshing(x => ({ ...x, [w.subject]: true }))
        refreshWatch({ subject: w.subject, mode: w.mode })
          .catch(() => {})
          .finally(() => { setRefreshing(x => ({ ...x, [w.subject]: false })); loadWatchlist() })
      })
    })()
  }, [])

  useEffect(() => {
    track('page_view', { page: 'console', referrer: typeof document !== 'undefined' ? document.referrer : '' })
    try {
      const saved = localStorage.getItem(STORE)
      if (saved) { const { run: r, phase: p } = JSON.parse(saved) as { run: Run; phase: Phase }; if (r?.step4) { setRun(r); setPhase(p === 'done' ? 'done' : 'paused') } }
    } catch {}
  }, [])
  const persist = (r: Run | null, p: Phase) => { try { r ? localStorage.setItem(STORE, JSON.stringify({ run: r, phase: p })) : localStorage.removeItem(STORE) } catch {} }

  useEffect(() => {
    if (phase !== 'running') return
    const started = Date.now()
    const timer = window.setInterval(() => setElapsed(Math.floor((Date.now() - started) / 1000)), 500)
    return () => clearInterval(timer)
  }, [phase])

  const started = phase !== 'idle' && !!run
  // Once the research pass is in (paused or done) every tab is reachable:
  // Competition + a research-only Roadmap can be generated without interviews.
  // Interviews just gets the 'attention' dot while a run is paused.
  const navState = (i: number): NavState => phase === 'idle' || phase === 'running' ? 'locked' : (phase === 'paused' && i === 2 ? 'attention' : 'ready')
  const runScout = async () => {
    if (!brief.trim()) return
    track('console_run', { brief: brief.slice(0, 200), mode, mock: MOCK })
    setError(''); setElapsed(0); setPhase('running'); setSelectedNav(0)
    try {
      const res: StartResponse = MOCK
        ? await new Promise((r) => setTimeout(() => r(mockStartResponse), 3000))
        : await startRun({ raw: brief, mode, budget: Math.max(1, Math.min(6, Number(loops) || 2)) })
      const next: Run = { threadId: res.thread_id, resumeToken: res.resume_token, step4: res.step4, final: null }
      setRun(next); persist(next, 'paused'); setPhase('paused'); setSelectedNav(0)
    } catch (e) {
      setError(errText(e, 'Scout could not reach the research service — is the backend awake?'))
      setPhase('idle')
    }
  }
  const finish = (final: FinalResponse) => { if (!run) return; track('console_resume', { subject: run.step4.subject }); const next = { ...run, final }; setRun(next); persist(next, 'done'); setPhase('done'); setSelectedNav(3) }
  const newRun = () => { setBrief(''); setPhase('idle'); setRun(null); persist(null, 'idle'); setElapsed(0); setSelectedNav(0); setError('') }

  // Generate Competition + Roadmap straight from the research, no interviews:
  // a resume with empty feedback. The competitive teardown is research-derived,
  // so it comes out complete; the roadmap is drafted from unresolved assumptions.
  const [generating, setGenerating] = useState(false)
  const generateFromResearch = async () => {
    if (!run || generating) return
    setGenerating(true); setError('')
    track('console_resume', { subject: run.step4.subject, from_research: true })
    try {
      const res = MOCK
        ? await new Promise<typeof mockResumeResponse>((r) => setTimeout(() => r(mockResumeResponse), 2000))
        : await resumeRun({ thread_id: run.threadId, resume_token: run.resumeToken, source: 'manual', answers: [], notes: '' })
      const next = { ...run, final: res.final }; setRun(next); persist(next, 'done'); setPhase('done')
    } catch (e) { setError(errText(e, 'Could not generate — the run may have expired; try a new run.')) } finally { setGenerating(false) }
  }

  const exportBrief = () => {
    if (!run) return
    track('export_brief', { subject: run.step4.subject })
    const step = run.step4, f = run.final
    const date = new Date().toISOString().slice(0, 10)
    const subject = step.subject || 'untitled-run'
    const md = [`# Scout brief — ${subject} · ${date}`, '', `*Resolution: ${Math.round((f?.confidence ?? step.confidence) * 100)}% resolved · ${step.gap_count ?? 0} interview gaps.*`, '', '## What changed', ...(step.alerts ?? []).map(a => `- **${a.title}** — ${a.detail} → ${a.action}`), '', '## Top signals', ...(step.signals_ranked ?? []).map(s => `- **${s.signal}** — score ${s.score}, ${s.trend}; who: ${asList(s.who).join(', ')}\n  > ${s.quote}\n  [receipt](${s.source_url})`), '', '## Pain map', ...(step.pain_map ?? []).map(p => `- **${p.pain}** — ${p.detail}\n  > ${p.quote} ([receipt](${p.source_url}))`), '', '## Assumption ledger', '| ID | Statement | Status | Support |', '| --- | --- | --- | --- |', ...(step.assumptions ?? []).map(a => `| ${a.id} | ${a.statement} | ${a.status} | ${Math.round(a.confidence * 100)}% |`), '', '## Interview agenda', ...(step.questions ?? []).map((q, i) => `${i + 1}. ${q.question}${asList(q.closes).length ? ` — closes ${asList(q.closes).join(', ')}` : ''}\n   receipt: ${asList(q.grounded_in).join(', ')}`), '', '## Competition', ...(f?.competitive?.battle_table ?? []).map(b => `- **${b.name}** (${b.pricing}) — serves ${b.segment}; strength: ${b.strength}; weakness: ${b.weakness}`), ...(f?.competitive?.whitespace ?? []).map(w => `- Whitespace: **${w.opportunity}** — ${w.why_now}`), ...(f?.competitive?.strategy ? [`- Beachhead: ${f.competitive.strategy.beachhead}`, `- Wedge: ${f.competitive.strategy.wedge}`, `- Moat: ${f.competitive.strategy.moat}`, ...f.competitive.strategy.first_90_days.map((x, i) => `  ${i + 1}. ${x}`)] : []), '', '## Roadmap candidates', ...(f?.proposed_features ?? []).map((x, i) => `${i + 1}. **${x.title}** — ${Math.round(x.confidence * 100)}% confidence${x.assumption_id ? `; closes ${x.assumption_id}` : ''}`), '', '## Blue ocean', ...(f?.blue_ocean ?? []).map(b => `- **${b.opportunity}** — ${b.why}`), '', 'Generated by Scout — every number above carries receipts back to real voices.'].join('\n')
    const blob = new Blob([md], { type: 'text/markdown;charset=utf-8' })
    const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `scout-brief-${subject.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')}-${date}.md`; link.click(); URL.revokeObjectURL(link.href)
  }

  const step4 = run?.step4
  const resolvedPct = step4 ? Math.round(step4.confidence * 100) : 0
  const gaps = step4 ? (step4.needs_human?.length || step4.gap_count || 0) : 0
  const watchedNow = step4 ? watchlist.some(w => w.subject.toLowerCase() === step4.subject.toLowerCase() && w.mode === step4.mode) : false
  const toggleWatch = async () => { if (!step4 || MOCK) return; try { await setWatch({ subject: step4.subject, mode: step4.mode, watch: !watchedNow }); await loadWatchlist() } catch {} }

  return <main className="min-h-screen bg-background text-foreground">
    <header className="sticky top-0 z-20 flex min-h-16 w-full items-center justify-between gap-5 border-b border-border bg-background px-5 py-3 md:px-8">
      <div className="flex shrink-0 items-baseline gap-3"><span className="text-xl font-semibold tracking-[-0.04em]">Scout<span className="text-primary">.</span></span><span className="hidden font-mono text-[10px] uppercase tracking-[0.16em] text-muted-foreground sm:inline">0→1 Discovery Agent</span></div>
      {started && step4 && <div className="hidden min-w-0 items-center gap-2 md:flex" aria-label="Run status"><span className="status-chip max-w-[190px] truncate" title={step4.subject}>{step4.subject.slice(0, 26)}… <ChevronDown size={11}/></span>{phase === 'running' ? <span className="status-chip status-blue"><i/>researching · {elapsed}s</span> : <><span className="status-chip status-green"><i/>{resolvedPct}% resolved</span><span className="status-chip status-blue"><i/>{gaps} to ask</span>{phase === 'paused' && <span className="status-chip status-amber">paused — waiting on interviews</span>}</>}</div>}
      <div className="flex items-center gap-2"><button type="button" className="ghost-button" onClick={newRun}><Plus size={15}/> New run</button>{started && <button type="button" className="ghost-button" onClick={exportBrief}><Download size={14}/> Export brief</button>}{started && !MOCK && phase !== 'running' && <button type="button" title={watchedNow ? 'Scout listens to this market automatically — click to stop' : 'Auto-refresh this market weekly (and when stale on visit)'} className={`ghost-button ${watchedNow ? 'status-green' : ''}`} onClick={toggleWatch}><Eye size={14}/> {watchedNow ? 'Watching' : 'Watch'}</button>}</div>
    </header>
    <div className="mx-auto flex max-w-[1320px]">
      <aside className="sticky top-16 hidden h-[calc(100vh-4rem)] w-[198px] shrink-0 border-r border-border px-5 py-8 md:block"><nav aria-label="Discovery phases" className="space-y-1">{navItems.map((label, i) => { const state = navState(i); const unlocked = state !== 'locked'; return <button key={label} disabled={!unlocked} type="button" aria-current={selectedNav === i ? 'page' : undefined} onClick={() => unlocked && setSelectedNav(i)} className={`phase-row ${!unlocked ? 'phase-locked' : ''} ${selectedNav === i && unlocked ? 'bg-muted' : ''}`}><span className="font-mono text-[11px] text-muted-foreground">{i + 1}</span><span>{label}</span><span className={`phase-dot dot-${state}`} /></button>})}</nav></aside>
      <section className="min-w-0 flex-1 px-5 py-12 md:px-12 md:py-16">{phase === 'idle' || !run ? (phase === 'running' ? <Running elapsed={elapsed}/> : <IdleView {...{brief,setBrief,mode,setMode,loops,setLoops,runScout,error,watchlist,refreshing}}/>) : phase === 'running' ? <Running elapsed={elapsed}/> : selectedNav === 0 ? <Radar run={run} phase={phase}/> : selectedNav === 1 ? (run.final ? <Competition final={run.final}/> : <GenerateGate what="Competition" blurb="the positioning map, five forces, battle cards, and whitespace — all drawn from the market research Scout already did." generating={generating} onGenerate={generateFromResearch} error={error}/>) : selectedNav === 2 ? <Interviews run={run} onDone={finish}/> : (run.final ? <Roadmap run={run}/> : <GenerateGate what="Roadmap" blurb="a ranked, evidence-backed feature shortlist. Interviews sharpen it with validated evidence, but Scout can draft it from research alone." generating={generating} onGenerate={generateFromResearch} error={error}/>)}</section>
    </div>
  </main>
}

function IdleView({brief,setBrief,mode,setMode,loops,setLoops,runScout,error,watchlist,refreshing}:{brief:string;setBrief:(v:string)=>void;mode:string;setMode:(v:'product'|'industry')=>void;loops:string;setLoops:(v:string)=>void;runScout:()=>void;error:string;watchlist:WatchEntry[];refreshing:Record<string,boolean>}) { return <div className="mx-auto max-w-[650px] pt-8 md:pt-12"><div className="mb-8"><h1 className="text-balance text-4xl font-semibold tracking-[-0.055em] md:text-5xl">What are you building?</h1><p className="mt-4 text-base leading-6 text-muted-foreground">Find the signal before you build the product.</p></div><div className="rounded-xl border border-border bg-card p-5 md:p-6"><label htmlFor="brief" className="sr-only">Product idea or research prompt</label><textarea id="brief" value={brief} onChange={e=>setBrief(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();runScout()}}} placeholder="Paste a product idea, customer note, market question, or anything you want to explore…" className="min-h-48 w-full resize-y rounded-lg border border-border bg-background p-4 text-sm leading-6 outline-none focus:border-primary focus:ring-2 focus:ring-primary/15"/><div className="mt-5 grid gap-4 sm:grid-cols-[1fr_140px]"><label className="field-label">Mode<select value={mode} onChange={e=>setMode(e.target.value as 'product'|'industry')}><option value="product">Product</option><option value="industry">Industry</option></select></label><label className="field-label">Loops<input type="number" min="1" max="6" value={loops} onChange={e=>setLoops(e.target.value)}/></label></div><button type="button" className="primary-button mt-5" onClick={runScout}><Play size={14} fill="currentColor"/> Run Scout</button>{error && <p className="mt-4 text-sm text-[color:var(--color-neg)]">{error}</p>}{MOCK && <p className="mt-3 font-mono text-[10px] uppercase text-muted-foreground">preview mode — sample data, no live research</p>}</div>
  {!MOCK && watchlist.length > 0 && <div className="mt-6 rounded-xl border border-border bg-card p-5 md:p-6">
    <div className="mb-4 flex items-center justify-between gap-3"><h2 className="flex items-center gap-2 text-sm font-semibold"><Eye size={14} className="text-primary"/> Watchtower</h2><span className="eyebrow">refreshes weekly · and on visit when stale</span></div>
    <div className="space-y-3">{watchlist.map(w => { const busy = refreshing[w.subject] || w.refreshing; return <div key={w.subject + w.mode} className="flex flex-wrap items-center gap-2 border-b border-border pb-3 last:border-0 last:pb-0">
      <span className="text-sm font-medium">{w.subject}</span>
      {w.movement.rising > 0 && <span className="status-chip status-green">▲ {w.movement.rising} rising</span>}
      {w.movement.new > 0 && <span className="status-chip status-blue">✦ {w.movement.new} new</span>}
      {w.movement.fading > 0 && <span className="status-chip status-amber">▼ {w.movement.fading} fading</span>}
      {busy && <span className="status-chip status-blue"><LoaderCircle size={10} className="animate-spin"/> listening to the market…</span>}
      <span className="ml-auto font-mono text-[10px] text-muted-foreground">{w.runs_on_record} runs · {ago(w.last_run_at)}</span>
    </div>})}</div>
  </div>}</div> }
function Running({elapsed}:{elapsed:number}) { return <div className="mx-auto max-w-[650px] pt-12"><p className="eyebrow">Scout / Researching</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">Finding the signal<span className="text-primary">.</span></h1><p className="mt-4 text-base leading-6 text-muted-foreground">Researching the market · {elapsed}s elapsed — live runs take a few minutes.</p></div> }
function EmptyState({item}:{item:string}) { return <div className="mx-auto max-w-[760px] pt-8"><p className="eyebrow">{item} / Empty</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em]">{item} is next.</h1><p className="mt-4 text-muted-foreground">This view fills in once interviews come back and Scout proposes the roadmap.</p><div className="mt-8 rounded-xl border border-border bg-card p-6"><div className="flex min-h-40 items-center justify-center rounded-lg border border-dashed border-border text-sm text-muted-foreground">No {item.toLowerCase()} evidence yet.</div></div></div> }
function GenerateGate({what, blurb, generating, onGenerate, error}:{what:string; blurb:string; generating:boolean; onGenerate:()=>void; error:string}) { return <div className="mx-auto max-w-[760px] pt-8"><p className="eyebrow">Scout / {what}</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">{what}</h1><p className="mt-4 max-w-2xl text-base leading-6 text-muted-foreground">{blurb}</p><div className="mt-8 rounded-xl border border-border bg-card p-6"><p className="text-sm leading-6">No interviews needed — Scout drafts this from the research it already ran. You can still open <span className="font-medium text-foreground">Interviews</span> first to sharpen the roadmap with validated evidence; the competitive picture is the same either way.</p><button type="button" disabled={generating} className="primary-button mt-5" onClick={onGenerate}>{generating ? <><LoaderCircle size={14} className="animate-spin"/> analyzing the market…</> : <><Play size={14} fill="currentColor"/> Generate from research</>}</button>{generating && <p className="mt-3 font-mono text-[10px] uppercase text-muted-foreground">scraping competitors + synthesizing — a minute or two on a live run</p>}{error && <p className="mt-3 text-sm text-[color:var(--color-neg)]">{error}</p>}</div></div> }

function Interviews({run, onDone}:{run:Run; onDone:(f:FinalResponse)=>void}) {
  const step = run.step4
  const [selectedAssumption, setSelectedAssumption] = useState<string|null>(null)
  const [connector, setConnector] = useState('Manual paste')
  const [answers, setAnswers] = useState('')
  const [notes, setNotes] = useState('')
  const [transcripts, setTranscripts] = useState('')
  const [callIds, setCallIds] = useState('')
  const [gongFrom, setGongFrom] = useState('')
  const [gongTo, setGongTo] = useState('')
  const [mcpUrl, setMcpUrl] = useState('')
  const [mcpToken, setMcpToken] = useState('')
  const [mcpArgs, setMcpArgs] = useState('{}')
  const [tools, setTools] = useState<{name:string;description:string}[]>([])
  const [outreach, setOutreach] = useState<{their_words:string;source:string;url:string;how:string;message:string;closes:string[]}[]>([])
  const [busy, setBusy] = useState(false)
  const [err, setErr] = useState('')
  const status = (s: string) => `status-chip status-${s==='supported'?'green':s==='refuted'?'red':s==='needs_human'?'blue':'amber'}`
  const resume = async () => {
    setBusy(true); setErr('')
    try {
      const res = MOCK
        ? await new Promise<typeof mockResumeResponse>((r) => setTimeout(() => r(mockResumeResponse), 2000))
        : await (() => { const source = connector==='Gong'?'gong' as const:connector==='Paste transcripts'?'transcripts' as const:connector==='Custom MCP server'?'mcp' as const:'manual' as const; return resumeRun({thread_id:run.threadId,resume_token:run.resumeToken,source,answers:answers.split('\n').filter(Boolean),notes,...(source==='gong'?{gong:{call_ids:callIds.split('\n').filter(Boolean),...(gongFrom?{from:gongFrom}:{}),...(gongTo?{to:gongTo}:{})}}:{}),...(source==='mcp'?{mcp:{url:mcpUrl,token:mcpToken,tool:tools[0]?.name ?? '',args:JSON.parse(mcpArgs||'{}')}}:{}),...(source==='transcripts'?{transcripts:transcripts.split('\n---\n').filter(x=>x.trim()).map((x,i)=>({title:`Interview ${i+1}`,transcript:x}))}:{})}) })()
      onDone(res.final)
    } catch (e) { setErr(errText(e, 'Resume failed — the run may have expired.')) } finally { setBusy(false) }
  }
  const discover = async () => { if (!mcpUrl) return; setBusy(true); try { const res=await discoverMcpTools({url:mcpUrl,token:mcpToken}); setTools(res.tools ?? []) } catch { setErr('Could not reach that MCP server.') } finally { setBusy(false) } }
  const draft = async () => { setBusy(true); setErr(''); try { const res=await recruitOutreach({thread_id:run.threadId,resume_token:run.resumeToken}); setOutreach(res.outreach ?? []) } catch { setErr('Outreach drafting needs the live backend.') } finally { setBusy(false) }}
  const lane = (label:string, items:{name:string;live:boolean;line:string}[]) => <div><p className="eyebrow mb-3">{label}</p><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{items.map(x=><button key={x.name} type="button" disabled={!x.live} onClick={()=>x.live&&setConnector(x.name)} className={`rounded-lg border border-border bg-card p-3 text-left ${x.live?'hover:border-primary':''} ${connector===x.name?'border-primary ring-1 ring-primary':''} ${!x.live?'opacity-55':''}`}><div className="flex items-center justify-between gap-2 text-sm font-semibold"><span>{x.name}</span><span className={`font-mono text-[10px] ${x.live?'text-primary':'text-muted-foreground'}`}>{x.live?'● live':'○ planned'}</span></div><p className="mt-1 text-xs text-muted-foreground">{x.line}</p></button>)}</div></div>
  return <div className="mx-auto max-w-[980px]"><div className="mb-10"><p className="eyebrow">Scout / Interviews</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">Interviews</h1><p className="mt-4 max-w-2xl text-base leading-6 text-muted-foreground">The human loop — what research couldn&apos;t settle, the questions that will, and what you heard back.</p></div>
    <SectionCard><div className="flex items-end gap-5"><div className="font-mono text-5xl tabular-nums text-primary">{Math.round(step.confidence*100)}%</div><div><h2 className="text-lg font-semibold">{Math.round(step.confidence*100)}% resolved</h2><p className="mt-1 text-sm text-muted-foreground">{step.resolvable_count} web-resolvable · {step.gap_count} only a human can close (interview gap)</p></div></div></SectionCard>
    <SectionCard className="mt-4 overflow-hidden p-0"><div className="p-5 md:p-6"><SectionTitle>Assumptions</SectionTitle><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-xs"><thead className="border-y border-border font-mono text-[10px] uppercase text-muted-foreground"><tr><th className="py-3">ID</th><th>Statement</th><th>Status</th><th>Support %</th><th>Resolved %</th></tr></thead><tbody>{(step.assumptions??[]).map(a=><tr key={a.id} onClick={()=>setSelectedAssumption(selectedAssumption===a.id?null:a.id)} className={`cursor-pointer border-b border-border ${selectedAssumption===a.id?'bg-muted':''}`}><td className="py-3 font-mono text-primary">{a.id}</td><td className="pr-4">{a.statement}</td><td><span className={status(a.status)}>{a.status.replace('_',' ')}</span></td><td className="font-mono">{Math.round(a.confidence*100)}%</td><td className="font-mono">{a.status==='supported'?'100%':a.status==='refuted'?'0%':'—'}</td></tr>)}</tbody></table></div><p className="mt-4 text-xs text-muted-foreground">click an assumption to highlight the questions that close it</p></div></SectionCard>
    <SectionCard className="mt-4"><SectionTitle action={<AgendaQuality questions={step.questions ?? []}/>}>Question agenda</SectionTitle><div className="space-y-4">{(step.questions??[]).map((q,i)=>{const closes=asList(q.closes); const active=selectedAssumption? closes.includes(selectedAssumption):true; const mt=q.mom_test ?? scoreQuestion(q.question); return <div key={i} className={`border-b border-border pb-4 last:border-0 last:pb-0 ${active?'':'opacity-[.35]'}`}><div className="flex gap-3"><span className="font-mono text-primary">Q{i+1}</span><div className="min-w-0"><p className="text-sm font-medium">{q.question} {closes.map(id=><span key={id} title={step.assumptions?.find(a=>a.id===id)?.statement} className="status-chip status-blue ml-2">closes {id}</span>)}</p><div className="mt-2"><MomBadge mt={mt}/></div><p className="mt-2 font-mono text-[10px] text-muted-foreground">why · {q.why}</p><p className="mt-2 border-l-2 border-primary pl-3 text-xs text-muted-foreground">receipt: {asList(q.grounded_in).join(', ')} {q.source_url&&<a href={q.source_url} target="_blank" rel="noreferrer" className="ml-2 text-primary">source ↗</a>}</p></div></div></div>})}</div><p className="mt-4 text-xs text-muted-foreground">Scored against <span className="font-medium text-foreground">The Mom Test</span> — questions about real past behavior beat opinions and hypotheticals. Flags are heuristic, not gospel.</p></SectionCard>
    <SectionCard className="mt-4 space-y-6"><SectionTitle>Connector roster</SectionTitle>{lane('Feedback in · where finished interviews live',[{name:'Manual paste',live:true,line:'answers and notes'},{name:'Paste transcripts',live:true,line:'separate with ---'},{name:'Gong',live:true,line:'built — add key'},{name:'Custom MCP server',live:true,line:'connect a tool'},{name:'Fireflies',live:false,line:'via MCP'},{name:'Dovetail',live:false,line:'via MCP'},{name:'Zoom',live:false,line:'planned'}])}{lane('Recruiting out · get the interviews to happen',[{name:'From receipts',live:true,line:'turn evidence into asks'},{name:'Clay',live:false,line:'planned'},{name:'Apollo',live:false,line:'planned'},{name:'Calendly',live:false,line:'planned'}])}
      {connector==='Manual paste'&&<div className="grid gap-3 md:grid-cols-2"><textarea value={answers} onChange={e=>setAnswers(e.target.value)} placeholder="One answer per line" className="min-h-28 rounded-lg border border-border bg-background p-3 text-sm"/><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Notes" className="min-h-28 rounded-lg border border-border bg-background p-3 text-sm"/></div>}{connector==='Paste transcripts'&&<div><textarea value={transcripts} onChange={e=>setTranscripts(e.target.value)} placeholder="Paste interview transcripts…" className="min-h-40 w-full rounded-lg border border-border bg-background p-3 text-sm"/><p className="mt-2 text-xs text-muted-foreground">separate interviews with a line containing only ---</p></div>}{connector==='Gong'&&<div className="grid gap-3 md:grid-cols-3"><textarea value={callIds} onChange={e=>setCallIds(e.target.value)} placeholder="Call IDs, one per line" className="min-h-24 rounded-lg border border-border bg-background p-3 text-sm md:col-span-3"/><input aria-label="From ISO" value={gongFrom} onChange={e=>setGongFrom(e.target.value)} placeholder="From ISO (optional)" className="rounded-lg border border-border bg-background p-3 text-sm"/><input aria-label="To ISO" value={gongTo} onChange={e=>setGongTo(e.target.value)} placeholder="To ISO (optional)" className="rounded-lg border border-border bg-background p-3 text-sm"/></div>}{connector==='Custom MCP server'&&<div className="space-y-3"><div className="flex gap-2"><input value={mcpUrl} onChange={e=>setMcpUrl(e.target.value)} placeholder="Server URL" className="min-w-0 flex-1 rounded-lg border border-border bg-background p-3 text-sm"/><input value={mcpToken} onChange={e=>setMcpToken(e.target.value)} placeholder="Optional bearer token" className="min-w-0 flex-1 rounded-lg border border-border bg-background p-3 text-sm"/><button type="button" className="ghost-button" onClick={discover}>{busy?'Discovering…':'Discover tools'}</button></div>{tools.length>0&&<select className="w-full rounded-lg border border-border bg-background p-3 text-sm"><option>{tools[0].name} — {tools[0].description}</option></select>}<textarea value={mcpArgs} onChange={e=>setMcpArgs(e.target.value)} className="min-h-20 w-full rounded-lg border border-border bg-background p-3 font-mono text-xs" placeholder="Optional JSON args"/></div>}{connector==='From receipts'&&<div><button type="button" className="ghost-button" onClick={draft}>{busy?'Drafting…':'Draft outreach'}</button>{outreach.length>0&&<div className="mt-4 space-y-3">{outreach.map((o,i)=><div key={i} className="rounded-lg border border-border p-4"><p className="text-sm">&ldquo;{o.their_words}&rdquo; <a href={o.url} target="_blank" rel="noreferrer" className="text-primary">source ↗</a></p><p className="mt-2 font-mono text-[10px] text-muted-foreground">{o.how} · closes {asList(o.closes).join(', ')}</p><textarea defaultValue={o.message} className="mt-3 min-h-20 w-full rounded-lg border border-border bg-background p-3 text-sm"/><button type="button" className="ghost-button mt-2" onClick={()=>navigator.clipboard?.writeText(o.message)}>copy message</button></div>)}</div>}</div>}</SectionCard>
    {err && <p className="mt-4 text-sm text-[color:var(--color-neg)]">{err}</p>}
    <button type="button" disabled={busy} onClick={resume} className="primary-button mt-6">{busy?<><LoaderCircle size={14} className="animate-spin"/> reading the evidence…</>:<>Resume → propose features</>}</button>
  </div>
}

const MOCK_JOURNAL: JournalEntry[] = [
  { at: '2026-08-23', key: 3, run: 3, signal_count: 8, headline: '1 rising · 1 new · 4 new whitespace', rising: ['Synthesis is the real bottleneck'], new: ['Teams want evidence on roadmap bets'], fading: [], competitor_changes: ['Dovetail pricing: “$12/seat” → “$15/seat”'], new_whitespace: ['Interview-to-roadmap loop'] },
  { at: '2026-08-21', key: 2, run: 2, signal_count: 12, headline: '2 rising · 4 new', rising: ['Scattered research'], new: ['Decision context is a new pain'], fading: [], competitor_changes: [], new_whitespace: [] },
  { at: '2026-08-18', key: 1, run: 1, signal_count: 12, headline: 'baseline captured — 12 signals', rising: [], new: [], fading: [], competitor_changes: [], new_whitespace: [] },
]
function MarketJournal({subject, mode}:{subject:string; mode:'product'|'industry'}) {
  const [entries, setEntries] = useState<JournalEntry[]|null>(null)
  const [open, setOpen] = useState(false)
  useEffect(() => {
    if (MOCK) { setEntries(MOCK_JOURNAL); return }
    getJournal(subject, mode).then(j => setEntries(j.entries)).catch(() => setEntries([]))
  }, [subject, mode])
  if (!entries || entries.length < 2) return null // only meaningful once there's history
  const shown = open ? entries : entries.slice(0, 3)
  return <SectionCard className="mt-4"><SectionTitle action={entries.length > 3 ? <button type="button" className="ghost-button px-2.5 py-1.5 text-[10px]" onClick={() => setOpen(!open)}>{open ? 'show less' : `all ${entries.length} runs`}</button> : undefined}>Market journal · how this market moved</SectionTitle>
    <ol className="relative space-y-4 border-l border-border pl-5">{shown.map(e => <li key={e.key} className="relative"><span className="absolute -left-[23px] top-1.5 h-2.5 w-2.5 rounded-full border-2 border-background bg-primary"/><div className="flex flex-wrap items-baseline justify-between gap-2"><p className="text-sm font-medium">{e.headline}</p><span className="font-mono text-[10px] text-muted-foreground">{(e.at||'').slice(0,10)} · run {e.run} · {e.signal_count} signals</span></div><div className="mt-1.5 space-y-1">{e.rising.slice(0,2).map(x => <p key={x} className="truncate text-xs text-[color:var(--color-pos)]" title={x}>▲ rising · {x}</p>)}{e.new.slice(0,1).map(x => <p key={x} className="truncate text-xs text-primary" title={x}>✦ new · {x}</p>)}{e.competitor_changes.slice(0,1).map((x,j) => <p key={j} className="truncate text-xs text-[color:var(--color-neg)]" title={x}>⚔ {x}</p>)}{e.new_whitespace.slice(0,1).map((x,j) => <p key={j} className="truncate text-xs text-muted-foreground" title={x}>◇ whitespace · {x}</p>)}</div></li>)}</ol>
    <p className="mt-4 text-xs text-muted-foreground">Every listening pass writes a line here — the longitudinal record that a one-shot research tool can&apos;t give you.</p>
  </SectionCard>
}
function MomBadge({mt}:{mt:MomTest}) {
  if (mt.verdict === 'clean') return <span className="status-chip status-green"><Check size={11}/> Mom-Test clean{mt.behavioral ? ' · behavioral' : ''}</span>
  const f = mt.flags[0]
  return <span className="inline-flex flex-wrap items-center gap-2"><span className={`status-chip ${mt.verdict === 'leading' ? 'status-red' : 'status-amber'}`}><TriangleAlert size={11}/> {f?.type ?? 'flagged'} · {mt.score}</span>{f && <span className="text-[11px] text-muted-foreground">{f.why}. <span className="text-foreground">{f.fix}</span></span>}</span>
}
function AgendaQuality({questions}:{questions:Question[]}) {
  if (!questions.length) return null
  const scores = questions.map(q => (q.mom_test ?? scoreQuestion(q.question)))
  const avg = Math.round(scores.reduce((s,x)=>s+x.score,0)/scores.length)
  const clean = scores.filter(x=>x.verdict==='clean').length
  return <span className={`status-chip ${avg>=80?'status-green':avg>=55?'status-amber':'status-red'}`} title="Average Mom-Test score across the agenda">agenda quality {avg} · {clean}/{questions.length} clean</span>
}

function Radar({run, phase}:{run:Run; phase:Phase}) { const [expanded,setExpanded]=useState<number|null>(null); const [question,setQuestion]=useState(''); const [answer,setAnswer]=useState(''); const [citations,setCitations]=useState<{n:number;text:string;source:string;url:string}[]>([]); const [loading,setLoading]=useState(false); const [copied,setCopied]=useState(false); const [pain,setPain]=useState<number|null>(null); const step=run.step4; const final=phase==='done'?run.final:null; const alerts=step.alerts ?? []; const signals=step.signals_ranked ?? []; const pains=step.pain_map ?? []; const blue=final?.blue_ocean ?? []
  const digest=()=>{ const text=`# Scout digest — ${step.subject}\n\n## Alerts\n${alerts.map(a=>`- **${a.title}** — ${a.detail} → ${a.action}`).join('\n')}\n\n## Top signals\n${signals.slice(0,3).map(s=>`- ${s.signal} (${s.score})`).join('\n')}\n\n## Blue ocean\n${blue.map(b=>`- ${b.opportunity}: ${b.why}`).join('\n')}`; navigator.clipboard?.writeText(text); setCopied(true); setTimeout(()=>setCopied(false),1600) }
  const ask=async()=>{ if(!question.trim())return; track('ask', { question: question.slice(0, 200) }); setLoading(true); try { const res=await askScout({thread_id:run.threadId,question,resume_token:run.resumeToken}); setAnswer(res.answer); setCitations(res.citations ?? []) } catch { setAnswer('Scout could not reach the live evidence service, so this answer is unavailable right now.'); setCitations([]) } finally { setLoading(false) } }
  return <div className="mx-auto max-w-[980px]"><div className="mb-10"><p className="eyebrow">Scout / Radar</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">Radar</h1><p className="mt-4 max-w-2xl text-base leading-6 text-muted-foreground">What the market is saying — ranked signals, trajectories, and the gaps nobody owns.</p></div>
    <Alerts alerts={alerts} copied={copied} copy={digest}/><AskScoutCard {...{question,setQuestion,answer,citations,loading,ask}}/><SinceRun step={step}/><MarketJournal subject={step.subject} mode={step.mode}/><Signals signals={signals} expanded={expanded} setExpanded={setExpanded}/><PainMap pains={pains} pain={pain} setPain={setPain}/><BlueOcean items={blue} done={phase==='done'}/>
  </div> }

function SectionCard({children,className=''}:{children:React.ReactNode;className?:string}){return <section className={`rounded-xl border border-border bg-card p-5 md:p-6 ${className}`}>{children}</section>}
function SectionTitle({children,action}:{children:React.ReactNode;action?:React.ReactNode}){return <div className="mb-5 flex items-center justify-between gap-4"><h2 className="text-sm font-semibold tracking-[-0.01em]">{children}</h2>{action}</div>}
function Alerts({alerts,copied,copy}:{alerts:Alert[];copied:boolean;copy:()=>void}){return <SectionCard><SectionTitle action={<button type="button" className="ghost-button px-2.5 py-1.5 text-[10px]" onClick={copy}><Clipboard size={12}/>{copied?'copied ✓':'copy digest'}</button>}>Alerts · what changed in your market</SectionTitle>{alerts.length?<div className="divide-y divide-border">{alerts.map((a,i)=><div key={i} className="grid gap-2 py-4 first:pt-0 last:pb-0 sm:grid-cols-[auto_1fr]"><span className={`status-chip status-${a.kind==='rising'?'green':a.kind==='faded'?'amber':a.kind==='competitor'?'red':'blue'} w-fit self-start capitalize`}>{a.kind.replace('_',' ')}</span><div><p className="text-sm font-semibold">{a.title}</p><p className="mt-1 text-sm text-muted-foreground">{a.detail}</p><p className="mt-2 font-mono text-[10px] text-primary">→ {a.action}</p></div></div>)}</div>:<p className="text-sm text-muted-foreground">baseline captured — alerts activate from the next run on this subject</p>}</SectionCard>}
function AskScoutCard({question,setQuestion,answer,citations,loading,ask}:{question:string;setQuestion:(v:string)=>void;answer:string;citations:{n:number;text:string;source:string;url:string}[];loading:boolean;ask:()=>void}){return <SectionCard className="mt-4"><SectionTitle>Ask Scout</SectionTitle><div className="flex gap-2"><input aria-label="Ask Scout question" value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.nativeEvent.isComposing)ask()}} placeholder="e.g. What do solo users complain about most?" className="min-w-0 flex-1 rounded-lg border border-border bg-background px-3 py-2.5 text-sm outline-none focus:border-primary"/><button type="button" className="primary-button" onClick={ask}>{loading?<><LoaderCircle size={14} className="animate-spin"/> reading the evidence…</>:<><Search size={14}/>Ask</>}</button></div>{answer&&<div className="mt-5 border-t border-border pt-5"><p className="text-sm leading-6" dangerouslySetInnerHTML={{__html:answer.replace(/</g,'&lt;').replace(/\[(\d+)\]/g,'<sup class="text-primary font-mono">[$1]</sup>')}}/><div className="mt-5 space-y-2">{citations.map(c=><div key={c.n} className="flex gap-2 text-xs"><span className="shrink-0 font-mono text-primary">[{c.n}] {c.source}</span><span className="min-w-0 flex-1 truncate text-muted-foreground">{c.text.slice(0,140)}</span><a href={c.url} target="_blank" rel="noreferrer" aria-label={`Open citation ${c.n}`}><ExternalLink size={13} className="shrink-0 text-primary"/></a></div>)}</div></div>}</SectionCard>}
function SinceRun({step}:{step:Step4}){const s=step.since_last_run; if(!s)return null; return <div className="my-5 rounded-xl border border-border bg-card px-5 py-4"><div className="flex flex-wrap items-center gap-2 text-xs"><span className="font-semibold">Since last run</span>{(s.rising??[]).map(x=><span className="status-chip status-green" key={x}>rising · {x}</span>)}{(s.new??[]).map(x=><span className="status-chip status-blue" key={x}>new · {x}</span>)}{(s.fading??[]).map(x=><span className="status-chip status-amber" key={x}>fading · {x}</span>)}{(s.gone??[]).map(x=><span className="status-chip" key={x}>gone · {x}</span>)}<span className="font-mono text-[10px] text-muted-foreground">{s.runs_on_record} runs on record</span></div>{(step.source_stats??[]).length>0&&<div className="mt-3 flex flex-wrap gap-2">{step.source_stats.map(x=><span key={x.source} title={x.hint} className={`status-chip ${x.fetched>0?'status-green':'status-red'}`}>{x.source} {x.fetched>0?'✓'+x.fetched:'⚠0'}</span>)}</div>}</div>}
function Severity({n}:{n:number}){return <span className="flex gap-1" aria-label={`${n} of 5 severity`}>{[1,2,3,4,5].map(i=><i key={i} className={`severity-dot ${i<=n?'filled':''}`}/>)}</span>}
function Spark({history}:{history:Signal['history']}){if(!history||history.length<2)return null; const points=history.map((p,i)=>`${i*(64/(history.length-1))},${18-Math.min(18,p.score/7)}`).join(' '); return <svg width="64" height="18" viewBox="0 0 64 18" aria-label="signal trend"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="1.5"/></svg>}
function Signals({signals,expanded,setExpanded}:{signals:Signal[];expanded:number|null;setExpanded:(v:number|null)=>void}){return <SectionCard className="mt-4 overflow-hidden p-0"><div className="p-5 pb-3 md:p-6 md:pb-3"><SectionTitle>Signals</SectionTitle></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="border-y border-border font-mono text-[10px] uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3">Signal</th><th>Freq</th><th>Sev</th><th>Score</th><th>Trend</th><th>Whitespace</th></tr></thead><tbody>{signals.map((s,i)=><Fragment key={s.signal}><tr onClick={()=>setExpanded(expanded===i?null:i)} className="cursor-pointer border-b border-border hover:bg-muted"><td className="px-5 py-4 font-medium">{s.signal}</td><td>{s.frequency}</td><td><Severity n={s.severity}/></td><td className="font-mono tabular-nums">{s.score}</td><td><span className={`status-chip status-${s.trend==='rising'?'green':s.trend==='fading'?'amber':'blue'} mr-2`}>{s.trend}</span><Spark history={s.history}/></td><td>{s.whitespace&&<span className="status-chip status-blue">yes</span>}</td></tr>{expanded===i&&<tr key={`${s.signal}-detail`}><td colSpan={6} className="bg-muted/40 p-5"><SignalDetail signal={s}/></td></tr>}</Fragment>)}</tbody></table></div></SectionCard>}
function SignalDetail({signal:s}:{signal:Signal}){return <div className="grid gap-6 lg:grid-cols-[1fr_250px]"><div><div className="flex flex-wrap gap-2"><span className="status-chip">{s.sentiment}</span>{(s.sources??[]).map(x=><span className="status-chip" key={x}>{x}</span>)}</div>{(s.who??[]).length>0&&<><p className="mt-4 font-mono text-[10px] uppercase text-muted-foreground">Who it hits</p><div className="mt-2 flex flex-wrap gap-2">{s.who.map(x=><span className="status-chip status-blue" key={x}>{x}</span>)}</div></>}<blockquote className="mt-4 border-l-2 border-primary pl-4 text-sm leading-6">&ldquo;{s.quote}&rdquo; {s.source_url&&<a href={s.source_url} target="_blank" rel="noreferrer" className="ml-2 font-mono text-[10px] text-primary">source ↗</a>}</blockquote><h3 className="mt-6 text-xs font-semibold">Evidence · {s.evidence_count ?? (s.evidence??[]).length} matched voices</h3><div className="mt-3 space-y-3">{(s.evidence??[]).map((e,i)=><EvidenceRow key={i} e={e}/>)}</div></div><div className="space-y-3">{s.gap&&<div className="rounded-lg border border-border bg-card p-4"><p className="eyebrow">Open question</p><p className="mt-2 text-sm leading-6">{s.gap}</p></div>}{s.next_step&&<div className={`rounded-lg p-4 ${s.gap_type==='ask_human'?'bg-primary text-primary-foreground':'border border-border bg-card'}`}><p className="font-mono text-[10px] uppercase">{s.gap_type==='ask_human'?'Ask a human':'Research it'}</p><p className="mt-2 text-sm leading-6">{s.next_step}</p></div>}</div></div>}
function EvidenceRow({e}:{e:Evidence}){return <div className="border-t border-border pt-3"><div className="flex justify-between gap-2 font-mono text-[10px] text-muted-foreground"><span>{e.source}{e.upvotes?` · ▲${e.upvotes}`:''}</span>{e.url&&<a href={e.url} target="_blank" rel="noreferrer" className="text-primary">↗</a>}</div><p className="mt-1 text-sm leading-6">{e.text}</p></div>}
function PainMap({pains,pain,setPain}:{pains:Pain[];pain:number|null;setPain:(v:number|null)=>void}){return <div className="mt-4"><div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-semibold">Pain map</h2><span className="eyebrow">matched voices</span></div><div className="grid gap-4 md:grid-cols-2">{pains.map((p,i)=><div key={p.pain} className="rounded-xl border border-border bg-card p-5"><button type="button" className="w-full text-left" onClick={()=>setPain(pain===i?null:i)}><div className="flex items-start justify-between gap-3"><h3 className="font-semibold">{p.pain}</h3><Severity n={p.severity}/></div><div className="mt-3 flex flex-wrap gap-2">{p.who&&<span className="status-chip status-blue">{asText(p.who)}</span>}<span className="font-mono text-[10px] text-primary">· {p.evidence_count ?? (p.evidence??[]).length} voices</span></div><p className="mt-3 text-sm text-muted-foreground">{p.detail}</p><blockquote className="mt-3 border-l-2 border-primary pl-3 text-sm leading-6">&ldquo;{p.quote}&rdquo;</blockquote></button>{pain===i&&(p.evidence??[]).length>0&&<div className="mt-4 border-t border-border pt-4"><p className="eyebrow">Receipts</p>{p.evidence.map((e,j)=><EvidenceRow e={e} key={j}/>)}</div>}</div>)}</div></div>}
function BlueOcean({items,done}:{items:{opportunity:string;why:string}[];done:boolean}){return <SectionCard className="mt-4"><SectionTitle><span className="text-primary">Blue ocean</span></SectionTitle>{items.length?<div className="grid gap-3 md:grid-cols-2">{items.map(x=><div key={x.opportunity} className="rounded-lg border border-primary/30 bg-primary/10 p-4"><h3 className="font-semibold">{x.opportunity}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{x.why}</p></div>)}</div>:<p className="text-sm text-muted-foreground">{done?'No persistent whitespace on record yet — blue ocean is earned across runs.':'Unlocks after interviews come back — persistence is earned across runs.'}</p>}</SectionCard>}

function ExportRoadmap({f}:{f:FinalResponse}) {
  const [copied, setCopied] = useState('')
  const feats = f.proposed_features ?? []
  const issuesMd = feats.map((x:ProposedFeature,i:number) => {
    const a = f.assumptions?.find(a => a.id === x.assumption_id)
    const ev = x.evidence?.[0]
    return `### ${i+1}. ${x.title}\n\n${x.rationale}\n\n- **Confidence:** ${Math.round(x.confidence*100)}%\n${x.assumption_id ? `- **Closes assumption:** ${x.assumption_id}${a ? ` — ${a.statement}` : ''}\n` : ''}${ev ? `- **Evidence:** "${ev.text}" — ${ev.source}${ev.url ? ` (${ev.url})` : ''}\n` : ''}`
  }).join('\n')
  const copy = (kind: string, text: string) => { navigator.clipboard?.writeText(text); track('export_roadmap', { kind, count: feats.length }); setCopied(kind); setTimeout(() => setCopied(''), 1600) }
  const csv = () => {
    const esc = (s: unknown) => `"${String(s ?? '').replace(/"/g, '""')}"`
    const rows = [['rank','title','confidence','rationale','closes_assumption','evidence_source','evidence_url']]
    feats.forEach((x:ProposedFeature,i:number) => rows.push([String(i+1), x.title, Math.round(x.confidence*100)+'%', x.rationale, x.assumption_id||'', x.evidence?.[0]?.source||'', x.evidence?.[0]?.url||''].map(esc)))
    const blob = new Blob([rows.map(r => r.join(',')).join('\n')], { type: 'text/csv;charset=utf-8' })
    const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `scout-roadmap-${f.subject.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}.csv`; link.click(); URL.revokeObjectURL(link.href)
    track('export_roadmap', { kind: 'csv', count: feats.length })
  }
  return <SectionCard className="mt-4"><SectionTitle>Ship it → your roadmap tool</SectionTitle><p className="text-sm text-muted-foreground">Hand these to Linear, Jira, or Productboard — each candidate becomes an issue with its evidence and the assumption it closes.</p><div className="mt-4 flex flex-wrap gap-2"><button type="button" className="ghost-button" onClick={() => copy('issues', issuesMd)}><Clipboard size={12}/>{copied === 'issues' ? 'copied ✓' : 'Copy as issues (Markdown)'}</button><button type="button" className="ghost-button" onClick={csv}><Download size={13}/> Download CSV</button></div></SectionCard>
}
function Roadmap({run}:{run:Run}) { const f=run.final; const [decisions,setDecisions]=useState<Record<string,Decision>>({}); const [saving,setSaving]=useState<string|null>(null); const [saveNote,setSaveNote]=useState<Record<string,string>>({}); useEffect(()=>{if(!f)return; getDecisions({subject:f.subject,mode:f.mode,snapshot_key:f.snapshot_key}).then(r=>setDecisions(Object.fromEntries(Object.entries(r.decisions??{}).map(([k,v])=>[k,v.decision])))).catch(()=>{})},[f]); const choose=async(title:string,id:string,d:Decision)=>{track('decision',{title,decision:d});setDecisions(x=>({...x,[title]:d}));setSaving(title);try{await saveDecision({subject:f!.subject,mode:f!.mode,snapshot_key:f!.snapshot_key,title,decision:d,assumption_id:id});setSaveNote(x=>({...x,[title]:'· saved'}))}catch{setSaveNote(x=>({...x,[title]:'saved locally only'}))}finally{setSaving(null)}}; return <div className="mx-auto max-w-[980px]"><div className="mb-10"><p className="eyebrow">Scout / Roadmap</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">Roadmap</h1><p className="mt-4 max-w-2xl text-base leading-6 text-muted-foreground">Ranked candidates with the evidence attached. Scout recommends — you decide.</p></div>{!f?<EmptyState item="Roadmap"/>:<><div className="space-y-3">{(f.proposed_features??[]).map((x,i)=><SectionCard key={x.title}><div className="flex gap-4"><span className="font-mono text-primary">{String(i+1).padStart(2,'0')}</span><div className="min-w-0 flex-1"><div className="flex justify-between gap-4"><div><h2 className="text-base font-semibold">{x.title}</h2><p className="mt-1 text-sm text-muted-foreground">{x.rationale}</p></div><span className="shrink-0 font-mono text-2xl tabular-nums text-[color:var(--color-pos)]">{Math.round(x.confidence*100)}%</span></div><div className="my-4 border-t border-border"/><p className="font-mono text-[10px] text-muted-foreground">{x.evidence?.[0]?.source??'evidence attached'} {x.evidence?.[0]?.text?.slice(0,100)} {x.assumption_id&&<span title={f.assumptions?.find(a=>a.id===x.assumption_id)?.statement} className="status-chip status-blue">closes {x.assumption_id}</span>}</p><div className="mt-4 flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] text-muted-foreground">Your call:</span>{(['build','park','reject'] as Decision[]).map(d=><button key={d} type="button" onClick={()=>choose(x.title,x.assumption_id,d)} className={`ghost-button capitalize ${decisions[x.title]===d?'status-'+(d==='build'?'green':d==='park'?'amber':'red'):''}`}>{d}</button>)}<span className="ml-auto font-mono text-[10px] text-muted-foreground">{saving===x.title?'saving…':decisions[x.title]?(saveNote[x.title]??'· saved'):'no decision yet'}</span></div></div></div></SectionCard>)}</div><SectionCard className="mt-4"><SectionTitle>Ranked feedback · signal vs noise</SectionTitle><div className="space-y-3">{(f.ranked_feedback??[]).map(r=><div key={r.item} className="flex gap-3 text-sm"><span className={`status-chip status-${r.kind==='signal'?'green':'amber'}`}>{r.kind} · p{r.priority}</span><span>{r.item}</span></div>)}</div></SectionCard><ExportRoadmap f={f}/><p className="mt-10 text-center font-mono text-[10px] text-muted-foreground">Scout recommends. It never ships. The human owns the call.</p></>}</div> }
function Competition({final:f}:{final:FinalResponse|null}) { return <div className="mx-auto max-w-[980px]"><div className="mb-10"><p className="eyebrow">Scout / Competition</p><h1 className="mt-4 text-4xl font-semibold tracking-[-0.055em] md:text-5xl">Competition</h1><p className="mt-4 max-w-2xl text-base leading-6 text-muted-foreground">Where the market sits, what it leaves open, and how Scout can win.</p></div>{!f?<EmptyState item="Competition"/>:<><SectionCard><SectionTitle>Positioning map</SectionTitle><svg viewBox="0 0 640 500" className="w-full" role="img" aria-label="Competitive positioning map"><rect x="70" y="25" width="520" height="400" fill="none" stroke="currentColor" strokeOpacity=".24"/><path d="M330 25v400M70 225h520" stroke="currentColor" strokeDasharray="4 4" strokeOpacity=".3"/>{(f.competitive?.positioning?.players ?? f.competitive?.players ?? []).map(p=>{const x=70+p.x*5.2,y=425-p.y*4;return <g key={p.name}><title>{p.note}</title>{p.is_subject&&<circle cx={x} cy={y} r="12" fill="none" stroke="currentColor" strokeDasharray="3 3"/>}<circle cx={x} cy={y} r="5" fill={p.is_subject?'currentColor':'#888'}/><text x={x} y={y-10} textAnchor={x>540?'end':'start'} fontSize="11" fontWeight={p.is_subject?'700':'400'} fill="currentColor">{p.name}</text></g>})}<text x="330" y="462" textAnchor="middle" fontSize="11" fill="currentColor">{f.competitive?.positioning?.x_axis?.label}</text><text x="72" y="42" fontSize="10" fill="currentColor">{f.competitive?.positioning?.y_axis?.high}</text><text x="72" y="417" fontSize="10" fill="currentColor">{f.competitive?.positioning?.y_axis?.low}</text><text x="70" y="447" fontSize="10" fill="currentColor">← {f.competitive?.positioning?.x_axis?.low}</text><text x="590" y="447" textAnchor="end" fontSize="10" fill="currentColor">{f.competitive?.positioning?.x_axis?.high} →</text></svg></SectionCard><SectionCard className="mt-4"><SectionTitle>Five forces</SectionTitle><div className="space-y-3">{(f.competitive?.five_forces??[]).map(x=><div key={x.force} className="grid gap-1 sm:grid-cols-[150px_auto_1fr] sm:items-center"><b className="text-sm">{x.force}</b><span className={`status-chip status-${x.level==='high'?'red':x.level==='medium'?'amber':'green'}`}>{x.level} · {x.score}/10</span><span className="text-sm text-muted-foreground">{x.insight}</span></div>)}</div></SectionCard><div className="mt-4 grid gap-4 md:grid-cols-2">{(f.competitive?.battle_table??[]).map(x=><SectionCard key={x.name}><div className="flex justify-between"><h2 className="font-semibold">{x.name}</h2><span className="font-mono text-[10px]">{x.pricing}</span></div><p className="mt-1 text-xs text-muted-foreground">serves {x.segment}</p><div className="mt-4 grid grid-cols-2 gap-2 text-xs"><div className="rounded-lg bg-green-500/10 p-3"><b>Strength</b><p className="mt-1">{x.strength}</p></div><div className="rounded-lg bg-red-500/10 p-3"><b>Weakness</b><p className="mt-1">{x.weakness}</p></div></div><div className="mt-3 rounded-lg bg-primary/10 p-3 text-xs text-primary"><b>How to win</b><p className="mt-1">{x.how_to_win}</p></div></SectionCard>)}</div><SectionCard className="mt-4"><SectionTitle>Whitespace</SectionTitle><div className="grid gap-3 md:grid-cols-3">{(f.competitive?.whitespace??[]).map((x,i)=><div key={x.opportunity} className="rounded-lg border border-border p-4"><span className="font-mono text-primary">{String(i+1).padStart(2,'0')}</span><h3 className="mt-3 font-semibold">{x.opportunity}</h3><p className="mt-2 text-sm"><b>Why now</b> {x.why_now}</p><p className="mt-2 text-xs italic text-muted-foreground">{x.evidence?.[0]?.text}</p></div>)}</div></SectionCard>{f.competitive?.strategy&&<SectionCard className="mt-4"><SectionTitle>Strategy</SectionTitle><div className="grid gap-3 md:grid-cols-3">{[['Beachhead · who to win first',f.competitive.strategy.beachhead],['Wedge · how you get in',f.competitive.strategy.wedge],['Moat · what compounds',f.competitive.strategy.moat]].map(([a,b])=><div className="border-l-2 border-primary pl-3" key={a}><p className="eyebrow">{a}</p><p className="mt-2 text-sm">{b}</p></div>)}</div><h3 className="mt-6 text-sm font-semibold">First 90 days</h3><ol className="mt-3 space-y-2 border-l border-border pl-5 text-sm">{(f.competitive.strategy.first_90_days??[]).map((x,i)=><li key={x}><span className="font-mono text-primary">{i+1}</span> {x}</li>)}</ol></SectionCard>}<SectionCard className="mt-4"><SectionTitle>Moves since last run</SectionTitle>{f.competitor_changes?.length?<ul className="list-disc pl-5 text-sm">{f.competitor_changes.map(x=><li key={x}>{x}</li>)}</ul>:<p className="text-sm text-muted-foreground">no competitor movement on record — diffs appear from the second run</p>}{(f.teardown??[]).length>0&&<div className="mt-6 overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="border-y border-border font-mono text-[10px] uppercase text-muted-foreground"><tr>{['Competitor','Pricing','Rating','Top complaint','Switched from','Recent news'].map(x=><th className="py-3" key={x}>{x}</th>)}</tr></thead><tbody>{(f.teardown??[]).map(x=><tr className="border-b border-border" key={x.competitor}>{[x.competitor,x.pricing,x.rating,x.complaint,x.switched_from,x.news].map((v,vi)=><td className="py-3 pr-3" key={vi}>{v}</td>)}</tr>)}</tbody></table></div>}</SectionCard></>}</div> }
